    graph = {i: [] for i in range(n)}
    for a, b in prerequisites:
        graph[a].append(b)

    visited = [False] * n
    result = []
    recursion_stack = [False] * n

    def dfs(node):
        if recursion_stack[node]:
            return False
        if visited[node]:
            return True
        recursion_stack[node] = True
        visited[node] = True
        for neighbor in graph[node]:
            if not dfs(neighbor):
                return False
        result.append(node)
        recursion_stack[node] = False
        return True

    for i in range(n):
        if not visited[i]:
            if not dfs(i):
                return []
    return result

