        return []

    # Create a list of all start and end points
    points = []
    for start, end in intervals:
        points.append((start, 'start'))
        points.append((end, 'end'))

    # Sort the points by value, and for ties, 'start' comes before 'end'
    points.sort(key=lambda x: (x[0], 0 if x[1] == 'start' else 1))

    merged = []
    current_start, current_end = None, None
    i = 0

    while i < len(points):
        if points[i][1] == 'start':
            if current_start is None:
                current_start = points[i][0]
                current_end = points[i][0]
            else:
                # If the current interval starts before the end of the current merged interval, merge
                if points[i][0] <= current_end:
                    current_end = max(current_end, points[i][0])
                else:
                    merged.append([current_start, current_end])
                    current_start = points[i][0]
                    current_end = points[i][0]
        else:
            if current_end is None:
                current_end = points[i][0]
            else:
                # If the current interval ends after the start of the current merged interval, merge
                if points[i][0] >= current_start:
                    current_end = max(current_end, points[i][0])
                else:
                    merged.append([current_start, current_end])
                    current_start = points[i][0]
                    current_end = points[i][0]
        i += 1

    if current_start is not None:
        merged.append([current_start, current_end])

    return merged

