from collections import Counter

def solve(nums, k):
    count = Counter(nums)
    frequencies = list(count.values())
    max_freq = max(frequencies)
    current = max_freq
    result = []
    for num in count:
        if current == max_freq:
            result.append(num)
            current -= 1
            if len(result) == k:
                break
        else:
            if count[num] == current:
                result.append(num)
                current -= 1
                if len(result) == k:
                    break
    return result

